"use client";
import { useRef } from "react";
import { typeInteractive, useTypeMotion, type TypographyMotionProps } from "./typography-shared";
import { typeEaseOut, typeStaggerProgress } from "./typography-math";
export interface RectangleTextRevealProps extends TypographyMotionProps {
  stagger?: number;
  maskColor?: string;
  radius?: number;
  direction?: "left" | "right";
}
export function RectangleTextReveal({
  text = "Keep moving.\nKeep discovering.\nMake every mile count.",
  stagger = 0.45,
  maskColor = "#e5e4e1",
  radius = 5,
  direction = "right",
  ...props
}: RectangleTextRevealProps) {
  const root = useRef<HTMLDivElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const rows = Array.from(root.current!.querySelectorAll<HTMLElement>("[data-type-line]"));
      rows.forEach((row, i) => {
        const q = typeEaseOut(typeStaggerProgress(p, i, rows.length, stagger));
        const glyph = row.firstElementChild as HTMLElement,
          mask = row.lastElementChild as HTMLElement;
        glyph.style.transform = `translateY(${(1 - q) * 115}%)`;
        mask.style.transform = `scaleX(${1 - q})`;
      });
    },
    `${text}:${stagger}:${direction}`,
  );
  return (
    <div
      ref={root}
      className={props.className}
      style={props.style}
      aria-label={text}
      data-typography="rectangle-text-reveal"
      {...typeInteractive(props.trigger)}
    >
      <div aria-hidden="true">
        {text.split("\n").map((line, i) => (
          <div
            key={i}
            data-type-line=""
            style={{
              position: "relative",
              overflow: "hidden",
              width: "fit-content",
              maxWidth: "100%",
              borderRadius: radius,
              marginBlock: ".08em",
            }}
          >
            <span style={{ display: "block" }}>{line || "\u00a0"}</span>
            <span
              data-type-mask=""
              style={{
                position: "absolute",
                inset: 0,
                background: maskColor,
                borderRadius: radius,
                transform: "scaleX(0)",
                transformOrigin: direction === "right" ? "right" : "left",
              }}
            />
          </div>
        ))}
      </div>
    </div>
  );
}
